using System;using System.Runtime.InteropServices;using System.Windows.Automation;
public static class OwnedHomeInput {
 [StructLayout(LayoutKind.Sequential)]public struct POINT{public int x,y;}
 [StructLayout(LayoutKind.Sequential)]public struct MOUSEINPUT{public int dx,dy;public uint data,flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Sequential)]public struct KEYBDINPUT{public ushort vk,scan;public uint flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Explicit,Size=32)]public struct UNION{[FieldOffset(0)]public MOUSEINPUT mouse;[FieldOffset(0)]public KEYBDINPUT key;}
 [StructLayout(LayoutKind.Sequential)]public struct INPUT{public uint type;public UNION data;}
 [DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint count,INPUT[] inputs,int size);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern bool GetPhysicalCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
 [DllImport("user32.dll")]static extern int GetSystemMetrics(int index);
 [StructLayout(LayoutKind.Sequential)]public struct RECT{public int left,top,right,bottom;}
 [DllImport("user32.dll")]static extern IntPtr WindowFromPoint(POINT p);
 [DllImport("user32.dll")]static extern uint GetDpiForWindow(IntPtr w);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr w,out uint pid);
 [DllImport("user32.dll")]static extern bool GetClientRect(IntPtr w,out RECT r);
 [DllImport("user32.dll")]static extern bool ClientToScreen(IntPtr w,ref POINT p);
 [DllImport("user32.dll")]static extern IntPtr GetThreadDpiAwarenessContext();
 [DllImport("user32.dll")]static extern int GetAwarenessFromDpiAwarenessContext(IntPtr c);
 static string logPath;static int cachedHwnd;

 static void Emit(INPUT value){var count=SendInput(1,new[]{value},Marshal.SizeOf<INPUT>());var error=Marshal.GetLastWin32Error();if(logPath!=null)System.IO.File.AppendAllText(logPath,"type="+value.type+" flags="+(value.type==0?value.data.mouse.flags:value.data.key.flags)+" count="+count+" error="+error+"\n");if(count!=1)throw new InvalidOperationException("SendInput failed");}
 static void Move(int x,int y){int left=GetSystemMetrics(76),top=GetSystemMetrics(77),width=GetSystemMetrics(78),height=GetSystemMetrics(79);if(width<=1||height<=1||x<left||y<top||x>=left+width||y>=top+height)throw new InvalidOperationException("Pointer outside display");Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{dx=(int)Math.Round((x-left)*65535.0/(width-1)),dy=(int)Math.Round((y-top)*65535.0/(height-1)),flags=0x8000|0x4000|1}}});}
 static void Button(bool down){Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{flags=down?2u:4u}}});}
 static void Foreground(AutomationElement w){if(GetForegroundWindow().ToInt64()!=cachedHwnd)throw new InvalidOperationException("Owned Home lost foreground");}
 public static void Run(string app,bool source,string id,string mode,double px,double py){
  IntPtr oldDpi=SetThreadDpiAwarenessContext(new IntPtr(-4));try{
  logPath=System.IO.Path.Combine(app,"homepage-input-transport.txt");System.IO.File.WriteAllText(logPath,"awareness="+GetAwarenessFromDpiAwarenessContext(GetThreadDpiAwarenessContext())+" screen="+GetSystemMetrics(78)+"x"+GetSystemMetrics(79)+"\n");
  if(id!="start"&&id!="open"&&id!="sample"&&id!="research"&&id!="HomePage-toggle")throw new InvalidOperationException("Fixed Home target required");
  if(mode!="pointer"&&mode!="enter"&&mode!="space"&&mode!="passive"&&mode!="passive-relative"&&mode!="neutral-enter"&&mode!="neutral-space")throw new InvalidOperationException("Fixed operation required");
  string path=System.IO.Path.Combine(app,"ReplicaProbe.exe");AutomationElement w=null;
  foreach(AutomationElement x in AutomationElement.RootElement.FindAll(TreeScope.Children,Condition.TrueCondition)){if(source?!x.Current.Name.StartsWith("HomePage · original isolation",StringComparison.Ordinal):x.Current.Name!="Replica HomePage verification")continue;var p=System.Diagnostics.Process.GetProcessById(x.Current.ProcessId);if(source?!p.MainModule.FileName.EndsWith(@"\Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):!string.Equals(p.MainModule.FileName,path,StringComparison.OrdinalIgnoreCase))continue;if(w!=null)throw new InvalidOperationException("Owned Home window not unique");w=x;}if(w==null)throw new InvalidOperationException("Owned Home window missing");cachedHwnd=w.Current.NativeWindowHandle;
  var bs=w.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,id));if(bs.Count!=1)throw new InvalidOperationException("Unique Home control required");var b=bs[0];var rect=b.Current.BoundingRectangle;double scale=rect.Height/(id=="HomePage-toggle"?24:id=="research"?44:52);if(scale<.9||scale>3||rect.Width/scale<90||rect.Width/scale>230)throw new InvalidOperationException("Home button geometry mismatch");
  SetForegroundWindow(new IntPtr(cachedHwnd));if(!mode.StartsWith("neutral-",StringComparison.Ordinal))b.SetFocus();System.Threading.Thread.Sleep(150);if(mode.StartsWith("neutral-",StringComparison.Ordinal)){var managed=System.IO.File.ReadAllText(System.IO.Path.Combine(app,"homepage-input.json"));if(!System.Text.RegularExpressions.Regex.IsMatch(managed,"\"focused\"\\s*:\\s*\"home-body\""))throw new InvalidOperationException("Exact managed neutral focus required");}else{var f=AutomationElement.FocusedElement;if(f.Current.ProcessId!=w.Current.ProcessId||f.Current.AutomationId!=id)throw new InvalidOperationException("Exact Home focus required");}Foreground(w);rect=b.Current.BoundingRectangle;
  if(mode=="enter"||mode=="space"||mode.StartsWith("neutral-",StringComparison.Ordinal)){ushort key=mode.EndsWith("space",StringComparison.Ordinal)?(ushort)32:(ushort)13;bool down=false;try{Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=key}}});down=true;System.Threading.Thread.Sleep(60);}finally{if(down)Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=key,flags=2}}});}}
  else{var p=mode=="passive-relative"?new System.Windows.Point(rect.Left+px*(rect.Height/52),rect.Top+py*(rect.Height/52)):mode=="passive"?new System.Windows.Point(px,py):new System.Windows.Point(rect.Left+rect.Width/2,rect.Top+rect.Height/2);var origin=new POINT();RECT client;GetClientRect(new IntPtr(w.Current.NativeWindowHandle),out client);ClientToScreen(new IntPtr(w.Current.NativeWindowHandle),ref origin);var physical=new POINT();GetPhysicalCursorPos(out physical);System.IO.File.AppendAllText(logPath,"dpi="+GetDpiForWindow(new IntPtr(w.Current.NativeWindowHandle))+" rect="+w.Current.BoundingRectangle+" client="+client.right+","+client.bottom+" screenOrigin="+origin.x+","+origin.y+" intended="+p.X+","+p.Y+" beforePhysical="+physical.x+","+physical.y+" hitHwnd="+WindowFromPoint(new POINT{x=(int)p.X,y=(int)p.Y})+" ownedHwnd="+w.Current.NativeWindowHandle+"\n");if(!w.Current.BoundingRectangle.Contains(p))throw new InvalidOperationException("Outside owned window");var old=new POINT();GetPhysicalCursorPos(out old);bool down=false;try{Move((int)Math.Round(p.X),(int)Math.Round(p.Y));System.Threading.Thread.Sleep(120);Foreground(w);POINT actual;GetPhysicalCursorPos(out actual);if(Math.Abs(actual.x-p.X)>1||Math.Abs(actual.y-p.Y)>1)throw new InvalidOperationException("Owned pointer moved before click");var hitHwnd=WindowFromPoint(actual);uint hitPid;GetWindowThreadProcessId(hitHwnd,out hitPid);if(hitHwnd==IntPtr.Zero||hitPid!=w.Current.ProcessId)throw new InvalidOperationException("Pointer hit another process");if(mode.StartsWith("passive",StringComparison.Ordinal)){foreach(string action in new[]{"start","open","sample","research"}){var control=w.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,action));if(control!=null&&control.Current.BoundingRectangle.Contains(p))throw new InvalidOperationException("Passive target intersects an action");}System.IO.File.WriteAllText(System.IO.Path.Combine(app,"homepage-passive-point.json"),"{\"x\":"+p.X.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"y\":"+p.Y.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"hit\":\""+"HWND-owned-process"+"\"}");}Button(true);down=true;System.Threading.Thread.Sleep(60);Button(false);down=false;}finally{if(down)Button(false);if(GetForegroundWindow().ToInt64()==cachedHwnd)Move(old.x,old.y);}}
  System.Threading.Thread.Sleep(300);Foreground(w);
  }finally{logPath=null;if(oldDpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(oldDpi);}
 }
 public static void Capture(string app){var old=SetThreadDpiAwarenessContext(new IntPtr(-4));try{AutomationElement w=null;foreach(AutomationElement x in AutomationElement.RootElement.FindAll(TreeScope.Children,Condition.TrueCondition)){if(x.Current.Name!="Replica HomePage verification")continue;if(!string.Equals(System.Diagnostics.Process.GetProcessById(x.Current.ProcessId).MainModule.FileName,System.IO.Path.Combine(app,"ReplicaProbe.exe"),StringComparison.OrdinalIgnoreCase))continue;if(w!=null)throw new InvalidOperationException("Owned capture uniqueness");w=x;}if(w==null)throw new InvalidOperationException("Own capture window missing");cachedHwnd=w.Current.NativeWindowHandle;Foreground(w);var r=w.Current.BoundingRectangle;var screen=new System.Windows.Rect(GetSystemMetrics(76),GetSystemMetrics(77),GetSystemMetrics(78),GetSystemMetrics(79));r.Intersect(screen);if(r.Width<600||r.Height<600)throw new InvalidOperationException("Own visible capture geometry");using(var b=new System.Drawing.Bitmap((int)r.Width,(int)r.Height)){using(var g=System.Drawing.Graphics.FromImage(b))g.CopyFromScreen((int)r.X,(int)r.Y,0,0,b.Size);b.Save(System.IO.Path.Combine(app,"homepage-visible-window.png"),System.Drawing.Imaging.ImageFormat.Png);}System.IO.File.WriteAllText(System.IO.Path.Combine(app,"homepage-visible-window.txt"),r.ToString());}finally{if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);}}

}
